// All remote text is inserted as text, or passed through an explicit README allowlist.
function sprite(name){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),use=document.createElementNS(ns,'use');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');use.setAttribute('href','#i-'+name);svg.append(use);return svg}
function safeGithubLink(url){try{const parsed=new URL(url,'https://github.com');return parsed.protocol==='https:'&&parsed.hostname==='github.com'?parsed.href:null}catch{return null}}
async function profileData(route,backup){try{const r=await fetch(PORTFOLIO_API+route,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw new Error();return await r.json()}catch(error){if(!backup)throw error;const r=await fetch('data/'+backup+'.json');if(!r.ok)throw error;return await r.json()}}
let allRepos=null;
function renderRepos(){const root=$('#repo-list'),term=$('#repo-search').value.trim().toLowerCase();root.replaceChildren();const repos=(allRepos||[]).filter(r=>(r.name+' '+(r.description||'')+' '+(r.language||'')).toLowerCase().includes(term));$('#repo-count').textContent='/ '+(allRepos?.length||0);repos.forEach(repo=>{const url=safeGithubLink(repo.html_url);if(!url)return;const a=document.createElement('a');a.className='repo-item';a.href=url;a.target='_blank';a.rel='noopener noreferrer';const head=document.createElement('div'),name=document.createElement('strong');name.textContent=repo.name;head.append(sprite('github'),name);const arrow=document.createElement('span');arrow.textContent='↗';head.append(arrow);const description=document.createElement('p');description.textContent=repo.description||'';const meta=document.createElement('div');meta.className='repo-meta';meta.textContent=[repo.language,repo.fork?'fork':null,repo.archived?'archived':null,repo.stargazers_count?'★ '+repo.stargazers_count:null].filter(Boolean).join(' · ');a.append(head,description,meta);root.append(a)});if(!repos.length){const p=document.createElement('p');p.className='fine';p.textContent='no matching repos.';root.append(p)}}
async function openRepos(){$('#repos-dialog').showModal();$('#repo-search').value='';if(allRepos){renderRepos();return}$('#repo-list').textContent='loading...';try{const data=await profileData('/repos','repos');allRepos=data.repos;renderRepos()}catch{$('#repo-list').textContent='couldn’t load the repositories.'}}
$('#repos-open').onclick=openRepos;$('#all-projects').onclick=openRepos;$('#repo-search').oninput=renderRepos;
function sanitizedReadme(html){const parsed=new DOMParser().parseFromString(html,'text/html'),allowed=new Set(['DIV','ARTICLE','SECTION','P','BR','HR','H1','H2','H3','H4','H5','H6','A','IMG','UL','OL','LI','STRONG','EM','B','I','CODE','PRE','BLOCKQUOTE','TABLE','THEAD','TBODY','TR','TH','TD','SUB','SUP','DETAILS','SUMMARY','SPAN','DEL']);function clean(node){if(node.nodeType===Node.TEXT_NODE)return document.createTextNode(node.textContent);if(node.nodeType!==Node.ELEMENT_NODE||!allowed.has(node.tagName))return document.createDocumentFragment();const el=document.createElement(node.tagName.toLowerCase());if(node.tagName==='A'||node.tagName==='IMG'){const attr=node.tagName==='A'?'href':'src',raw=node.getAttribute(attr);try{const url=new URL(raw,'https://github.com/rusetiq/rusetiq/');if(url.protocol==='https:'){el.setAttribute(attr,url.href);if(attr==='href'){el.target='_blank';el.rel='noopener noreferrer'}else{el.alt=node.getAttribute('alt')||'';el.loading='lazy'}}}catch{}}if(node.tagName==='IMG'&&/^[0-9]+%?$/.test(node.getAttribute('width')||''))el.setAttribute('width',node.getAttribute('width'));for(const child of node.childNodes)el.append(clean(child));return el}const fragment=document.createDocumentFragment();for(const child of parsed.body.childNodes)fragment.append(clean(child));return fragment}
let readmeLoaded=false;$('#readme-open').onclick=async()=>{$('#readme-dialog').showModal();if(readmeLoaded)return;$('#readme-content').textContent='loading...';try{const data=await profileData('/readme','readme');$('#readme-content').replaceChildren(sanitizedReadme(data.html));readmeLoaded=true}catch{$('#readme-content').textContent='couldn’t load the readme.'}};
let dayRequest=0;async function openContributionDay(day,label){const request=++dayRequest;$('#day-title').textContent=day.date;const root=$('#day-content');root.textContent='loading public activity...';$('#day-dialog').showModal();try{const data=await profileData('/github-day?date='+encodeURIComponent(day.date));if(request!==dayRequest)return;root.replaceChildren();const summary=document.createElement('p');summary.className='day-summary';summary.textContent=label;root.append(summary);data.repos.forEach(repo=>{const url=safeGithubLink(repo.url);if(!url)return;const link=document.createElement('a');link.className='day-repo';link.href=url;link.target='_blank';link.rel='noopener noreferrer';const text=document.createElement('strong');text.textContent=repo.name;const count=document.createElement('span');count.textContent=repo.activity+' ↗';link.append(sprite('github'),text,count);root.append(link)});if(!data.repos.length){const p=document.createElement('p');p.className='fine';p.textContent=day.count?'github doesn’t expose repository details for these contributions.':'no public contributions on this day.';root.append(p)}const source=document.createElement('a');source.className='day-source';source.href=data.source;source.target='_blank';source.rel='noopener noreferrer';source.textContent='view day on github ↗';root.append(source)}catch{if(request!==dayRequest)return;root.textContent='github couldn’t load this day. ';const link=document.createElement('a');link.href=`https://github.com/rusetiq?tab=overview&from=${day.date}&to=${day.date}`;link.target='_blank';link.rel='noopener noreferrer';link.textContent='view on github ↗';root.append(link)}}$('#day-dialog').addEventListener('close',()=>dayRequest++);
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}));
